/* KAT Command Center - documentation site.
 *
 * Everything the site shows comes from window.KCC_DOCS, which assets/content.js assigns. That file
 * is generated by tools/Build-Docs.ps1 and loaded with a plain <script> tag, because the site must
 * open straight from file:// and a browser refuses fetch/XHR of local files there. Never load site
 * content over the network here; tools/Build-Docs.ps1 -Validate rejects it.
 *
 * Routes are hash-based:
 *   #/work-items                    -> the Work Items article
 *   #/work-items/add-query-help     -> the same article, scrolled to that id
 *   #/releases/1.4/1.4.2            -> a page whose id is itself two segments ("releases/1.4")
 *   #/whats-new?priorVersion=1.3.9  -> the What's New view; see assets/whats-new.js for its parameters
 * The app's contextual "?" buttons deep-link with the first two forms, so an article id or an
 * anchor id that changes breaks a shipped build. tools/Build-Docs.ps1 -Validate checks them.
 *
 * Article markup is inserted with innerHTML, so a <script> inside an article never runs. Anything
 * an article needs to do is a delegated handler below. */

(() => {
	'use strict';

	const docs = window.KCC_DOCS;
	const nav = document.getElementById('kdNav');
	const article = document.getElementById('kdArticle');
	const toc = document.getElementById('kdToc');
	const pager = document.getElementById('kdPager');
	const search = document.getElementById('kdSearch');
	const results = document.getElementById('kdSearchResults');
	const sidebar = document.getElementById('kdSidebar');
	const scrim = document.getElementById('kdScrim');
	const navToggle = document.getElementById('kdNavToggle');
	const themeToggle = document.getElementById('kdThemeToggle');
	const toast = document.getElementById('kdToast');

	const siteTitle = 'KAT Command Center';

	const icons = {
		home: '<path d="M4 11 12 4l8 7v9H4z"/><path d="M9 20v-6h6v6"/>',
		dashboard: '<rect x="3" y="4" width="8" height="7" rx="1"/><rect x="13" y="4" width="8" height="7" rx="1"/><rect x="3" y="13" width="18" height="7" rx="1"/>',
		release: '<circle cx="5" cy="12" r="2"/><circle cx="12" cy="6" r="2"/><circle cx="19" cy="12" r="2"/><path d="m7 11 3.5-3.5M13.5 7.5 17 11M7 13h10"/>',
		diff: '<path d="M6 4v13a3 3 0 0 0 3 3h1M6 8h7a3 3 0 0 1 3 3v9M3 7l3-3 3 3M13 17l3 3 3-3"/>',
		calcengine: '<path d="M6 4h12v16H6zM9 8h6m-6 4h6m-6 4h4"/>',
		workitems: '<path d="M5 4h14v16H5zM8 8h8M8 12h5M8 16h7"/>',
		metrics: '<path d="M5 19V9m5 10V5m5 14v-7m5 7V8"/>',
		sitescope: '<rect x="3" y="5" width="18" height="13" rx="2"/><path d="M6 12h2.5l1.5-3 2 6 1.5-3H18"/>',
		notes: '<path d="M6 3h9l3 3v15H6z"/><path d="M14 3v4h4M9 11h6M9 15h6"/>',
		help: '<circle cx="12" cy="12" r="9"/><path d="M9.8 9a2.4 2.4 0 1 1 3.8 2c-1 .7-1.6 1.2-1.6 2.5M12 17h.01"/>'
	};

	function iconSvg(name) {
		return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.help}</svg>`;
	}

	function escapeHtml(value) {
		return String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
	}

	function href(pageId, anchor, query) {
		return `#/${pageId}${anchor ? '/' + anchor : ''}${query ? '?' + query : ''}`;
	}

	if (!docs || !docs.pages) {
		article.innerHTML = '<h1>Documentation unavailable</h1><p>assets/content.js did not load. Run <code>tools/Build-Docs.ps1</code> to generate it.</p>';
		return;
	}

	// Reading order for the pager: every page the navigation lists, in the order it lists them.
	const order = [];
	for (const section of docs.sections) {
		for (const group of section.groups) {
			for (const id of group.pages) {
				if (docs.pages[id]) order.push(id);
			}
		}
	}

	let currentId = null;

	/* ---------- theme ---------- */

	themeToggle.addEventListener('click', () => {
		const next = document.documentElement.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
		document.documentElement.setAttribute('data-theme', next);
		try { localStorage.setItem('kcc-docs-theme', next); } catch { /* storage can be disabled */ }
	});

	/* ---------- mobile nav ---------- */

	function closeNav() {
		sidebar.classList.remove('is-open');
		scrim.hidden = true;
		navToggle.setAttribute('aria-expanded', 'false');
	}

	navToggle.addEventListener('click', () => {
		const open = sidebar.classList.toggle('is-open');
		scrim.hidden = !open;
		navToggle.setAttribute('aria-expanded', String(open));
	});
	scrim.addEventListener('click', closeNav);

	/* ---------- navigation ---------- */

	function buildNav() {
		const html = [];
		for (const section of docs.sections) {
			html.push(`<div class="kd-nav-section">${escapeHtml(section.title)}</div>`);
			let listed = 0;
			for (const group of section.groups) {
				const pages = group.pages.filter(id => docs.pages[id]);
				if (!pages.length) continue;
				if (group.title) html.push(`<div class="kd-nav-group">${escapeHtml(group.title)}</div>`);
				for (const id of pages) {
					const page = docs.pages[id];
					html.push(`<a href="${href(id)}" data-page="${escapeHtml(id)}">${iconSvg(page.icon)}<span>${escapeHtml(page.navTitle || page.title)}</span></a>`);
					// A version page's patches, shown only while that page is open.
					if (page.children && page.children.length) {
						html.push(`<div class="kd-nav-children" data-children-of="${escapeHtml(id)}" hidden>` +
							page.children.map(child => `<a href="${href(id, child.anchor)}" data-child="${escapeHtml(child.anchor)}">${escapeHtml(child.title)}</a>`).join('') +
							'</div>');
					}
					listed++;
				}
			}
			if (!listed && section.emptyText) html.push(`<div class="kd-nav-empty">${escapeHtml(section.emptyText)}</div>`);
		}
		nav.innerHTML = html.join('');
	}

	function markActiveNav(id, anchor) {
		nav.querySelectorAll('a[data-page]').forEach(a => {
			const active = a.dataset.page === id;
			a.classList.toggle('is-active', active);
			if (active) a.setAttribute('aria-current', 'page');
			else a.removeAttribute('aria-current');
		});
		nav.querySelectorAll('.kd-nav-children').forEach(list => {
			list.hidden = list.dataset.childrenOf !== id;
			list.querySelectorAll('a').forEach(a => a.classList.toggle('is-active', !list.hidden && a.dataset.child === anchor));
		});
	}

	// Headings inside a demo are part of the sample UI (a modal's title, a card's header), not the
	// article's outline, so they stay out of the table of contents.
	function outlineHeadings() {
		return [...article.querySelectorAll('h2[id], h3[id]')].filter(h => !h.closest('.tfs-release, .cc-help-demo'));
	}

	// pageOf names the real page an anchor lives on; in the What's New view that differs per patch.
	function buildToc(headings, pageOf) {
		if (headings.length < 2) {
			toc.innerHTML = '';
			return;
		}

		const links = headings.map(h => {
			const label = h.textContent.trim();
			const pageId = pageOf ? pageOf(h) : currentId;
			const permalink = document.createElement('a');
			permalink.className = 'kd-anchor';
			permalink.href = href(pageId, h.id);
			permalink.textContent = '#';
			permalink.setAttribute('aria-label', `Link to ${label}`);
			h.appendChild(permalink);
			// In the What's New view a TOC click scrolls in place (see the toc click handler) rather
			// than leaving for the patch's own page.
			return `<a class="${h.tagName === 'H3' ? 'is-sub' : ''}" href="${href(pageId, h.id)}" data-target="${escapeHtml(h.id)}">${escapeHtml(label)}</a>`;
		});

		toc.innerHTML = `<div class="kd-toc-title">On this page</div>${links.join('')}`;
	}

	let trackedHeadings = [];
	let scrollQueued = false;

	function queueActiveHeading() {
		if (scrollQueued) return;
		scrollQueued = true;
		requestAnimationFrame(() => { scrollQueued = false; updateActiveHeading(); });
	}
	window.addEventListener('scroll', queueActiveHeading, { passive: true });
	window.addEventListener('resize', queueActiveHeading, { passive: true });

	// The last heading scrolled past, rather than intersection, so exactly one entry is always
	// active - including at the very top and the very bottom of a short article.
	function updateActiveHeading() {
		if (!trackedHeadings.length) return;

		const scroller = document.scrollingElement || document.documentElement;
		const atBottom = scroller.scrollTop + scroller.clientHeight >= scroller.scrollHeight - 2;

		let active = trackedHeadings[0];
		if (atBottom) {
			active = trackedHeadings[trackedHeadings.length - 1];
		} else {
			for (const heading of trackedHeadings) {
				if (heading.getBoundingClientRect().top > 110) break;
				active = heading;
			}
		}

		toc.querySelectorAll('a').forEach(a => a.classList.toggle('is-active', a.dataset.target === active.id));
	}

	function buildPager(id) {
		const index = order.indexOf(id);
		if (index === -1) {
			pager.innerHTML = '';
			return;
		}
		const prev = docs.pages[order[index - 1]];
		const next = docs.pages[order[index + 1]];
		const parts = [];
		if (prev) parts.push(`<a href="${href(prev.id)}"><small>Previous</small><strong>${escapeHtml(prev.title)}</strong></a>`);
		if (next) parts.push(`<a class="kd-pager-next" href="${href(next.id)}"><small>Next</small><strong>${escapeHtml(next.title)}</strong></a>`);
		pager.innerHTML = parts.join('');
	}

	function scrollToAnchor(anchor) {
		const target = anchor && document.getElementById(anchor);
		if (target && article.contains(target)) target.scrollIntoView({ block: 'start' });
		else window.scrollTo({ top: 0, behavior: 'auto' });
	}

	// A page id may itself contain a slash (a release page is "releases/1.4"), so the longest
	// prefix naming a real page wins and whatever follows is the anchor. A query after "?" belongs
	// to the What's New view; any other page ignores it.
	function parseRoute(hash) {
		const raw = hash.replace(/^#\/?/, '');
		const cut = raw.indexOf('?');
		const path = cut === -1 ? raw : raw.slice(0, cut);
		const query = cut === -1 ? '' : raw.slice(cut + 1);
		const segments = path.split('/').filter(Boolean).map(s => {
			try { return decodeURIComponent(s); } catch { return s; }
		});
		if (!segments.length) {
			// index.html?priorVersion=... with no route is the What's New entry too.
			const params = whatsNew ? whatsNew.readParams('', location.search) : {};
			return 'priorVersion' in params || 'version' in params ? { whatsNew: true, query } : { id: docs.defaultPage, anchor: '', query };
		}
		if (whatsNew && segments[0] === whatsNewRoute && !docs.pages[whatsNewRoute]) return { whatsNew: true, query };
		for (let take = segments.length; take > 0; take--) {
			const id = segments.slice(0, take).join('/');
			if (docs.pages[id]) return { id, anchor: segments.slice(take).join('/'), query };
		}
		return { id: segments[0], anchor: '', query, missing: true };
	}

	function showPage(key, html, title) {
		currentId = key;
		article.innerHTML = html;
		document.title = `${title} — ${siteTitle}`;
	}

	function render() {
		const hash = location.hash;
		// A plain in-page fragment (the skip link) is the browser's job, not a route.
		if (hash && !hash.startsWith('#/')) return;

		const route = parseRoute(hash);
		const { id, anchor, missing } = route;

		if (route.whatsNew) {
			renderWhatsNew(route.query);
			closeNav();
			return;
		}
		whatsNewView = null;

		if (missing) {
			currentId = null;
			trackedHeadings = [];
			article.innerHTML = `<h1>Not found</h1><p>There is no page named <code>${escapeHtml(id)}</code>. <a href="${href(docs.defaultPage)}">Start here</a> or use search.</p>`;
			toc.innerHTML = '';
			pager.innerHTML = '';
			markActiveNav(null);
			document.title = `Not found — ${siteTitle}`;
			closeNav();
			return;
		}

		if (id !== currentId) {
			const page = docs.pages[id];
			showPage(id, page.html, page.title);
			trackedHeadings = outlineHeadings();
			buildToc(trackedHeadings);
			buildPager(id);
			article.focus({ preventScroll: true });
		}

		markActiveNav(id, anchor);
		scrollToAnchor(anchor);
		updateActiveHeading();
		closeNav();
	}

	/* ---------- What's New ---------- */

	const whatsNew = window.KccWhatsNew;
	const whatsNewRoute = 'whats-new';
	let whatsNewView = null;

	function patchSection(release) {
		const page = docs.pages[release.page];
		if (!page) return null;
		const template = document.createElement('template');
		template.innerHTML = page.html;
		return template.content.querySelector(`section.kd-patch[data-version="${CSS.escape(release.version)}"]`);
	}

	function noticeHtml(text, dismissible) {
		return `<div class="kd-whats-new-notice" role="status"><span>${text}</span>` +
			(dismissible ? '<button type="button" class="kd-notice-dismiss" data-whats-new-dismiss aria-label="Dismiss">Dismiss</button>' : '') +
			'</div>';
	}

	/* The view the app opens after an update. One version line: its own page, with the unseen
	 * patches highlighted. More than one: a page assembled from each line's patches, oldest first,
	 * so an upgrade across version lines still reads as one chronological list. */
	function renderWhatsNew(query) {
		const params = whatsNew.readParams(query, location.search);
		const selection = whatsNew.selectRange(docs.releases || [], params);
		const key = `${whatsNewRoute}?${query}|${location.search}`;
		const rerender = key !== currentId;

		if (selection.mode === 'empty') {
			whatsNewView = null;
			showPage(key, '<header class="cc-help-article-header"><div class="cc-help-eyebrow">Release Notes</div><h1>What\'s New</h1></header><p class="kd-release-empty">No release notes have been published yet.</p>', "What's New");
			trackedHeadings = [];
			toc.innerHTML = '';
			pager.innerHTML = '';
			markActiveNav('releases');
			return;
		}

		const byVersion = new Map((docs.releases || []).map(r => [r.version, r]));
		const patches = selection.patches.map(p => byVersion.get(p.version) || p);
		const minors = [...new Set(patches.map(p => p.minor))];
		const count = patches.length === 1 ? '1 update' : `${patches.length} updates`;

		const notes = [];
		if (selection.invalidPrior) notes.push(`<p class="kd-whats-new-note">The previous version <code>${escapeHtml(params.priorVersion)}</code> is not a version number, so this shows the latest update.</p>`);
		if (selection.invalidVersion) notes.push(`<p class="kd-whats-new-note"><code>${escapeHtml(params.version)}</code> is not a version number, so this shows the newest published notes.</p>`);
		if (selection.versionUnpublished) notes.push(`<p class="kd-whats-new-note">The notes for version ${escapeHtml(params.version)} are not published yet; these are the newest available.</p>`);
		if (selection.priorBeforeHistory) notes.push(`<p class="kd-whats-new-note">Release notes start at ${escapeHtml(docs.releases[0].version)}; see each version's introduction for earlier changes.</p>`);

		let notice = '';
		if (selection.mode === 'since') notice = noticeHtml(`See what's new since version ${escapeHtml(selection.prior)}: ${count}, highlighted below.`, true);
		else if (selection.mode === 'current') notice = noticeHtml(`Nothing new since version ${escapeHtml(selection.prior)}. This is the latest update.`, true);

		let html;
		let pageKey;
		if (selection.crossMinor) {
			const parts = [`<header class="cc-help-article-header"><div class="cc-help-eyebrow">Release Notes</div><h1>What's new since ${escapeHtml(selection.prior)}</h1>` +
				`<p class="cc-help-lede">${count} across versions ${minors.map(escapeHtml).join(', ')}, oldest first.</p></header>`];
			for (const minor of minors) {
				parts.push(`<div class="kd-since-minor"><a href="${href('releases/' + minor)}">Version ${escapeHtml(minor)}</a></div>`);
				for (const patch of patches.filter(p => p.minor === minor)) {
					const section = patchSection(patch);
					if (section) parts.push(section.outerHTML);
				}
			}
			html = parts.join('');
			pageKey = null;
		} else {
			pageKey = patches[0].page;
			html = docs.pages[pageKey] ? docs.pages[pageKey].html : '';
		}

		if (rerender) {
			showPage(key, html, "What's New");
			const firstPatch = article.querySelector(`section.kd-patch[data-version="${CSS.escape(patches[0].version)}"]`);
			// Directly above the first unseen patch, so the reader lands on the notice and the patch
			// together; the cross-version view starts with its own heading, so the notice leads it.
			const anchorEl = pageKey && firstPatch ? firstPatch : null;
			const banner = notice + notes.join('');
			if (anchorEl) anchorEl.insertAdjacentHTML('beforebegin', banner);
			else article.insertAdjacentHTML('afterbegin', banner);
			scheduleNoticeDismiss();
			if (selection.mode === 'since') {
				for (const patch of patches) {
					const section = article.querySelector(`section.kd-patch[data-version="${CSS.escape(patch.version)}"]`);
					if (!section) continue;
					section.classList.add('kd-patch--new');
					section.querySelector('.kd-patch-meta')?.insertAdjacentHTML('beforeend', '<span class="kd-badge kd-badge-new">New</span>');
				}
			}
			const releasePageOf = heading => heading.closest('section.kd-patch') ? byVersion.get(heading.closest('section.kd-patch').dataset.version)?.page || 'releases' : pageKey || 'releases';
			trackedHeadings = outlineHeadings();
			buildToc(trackedHeadings, releasePageOf);
			if (pageKey) buildPager(pageKey); else pager.innerHTML = '';
			article.focus({ preventScroll: true });
		}
		whatsNewView = { pageKey };

		const newestMinor = minors[minors.length - 1];
		markActiveNav(pageKey || `releases/${newestMinor}`, pageKey ? patches[0].version : '');
		const landing = pageKey
			? article.querySelector('.kd-whats-new-notice, .kd-whats-new-note') || article.querySelector(`section.kd-patch[data-version="${CSS.escape(patches[0].version)}"]`)
			: null;
		if (landing && landing.previousElementSibling) landing.scrollIntoView({ block: 'start' });
		else window.scrollTo({ top: 0, behavior: 'auto' });
		updateActiveHeading();
	}

	// The notice leaves on its own, but only the notice: the NEW highlights stay for the rest of the
	// read, because they are what tells the reader which patches are theirs. Pointing at it or
	// focusing its button holds it open.
	const noticeLifetimeMs = 5000;
	let noticeTimer = 0;

	function scheduleNoticeDismiss() {
		clearTimeout(noticeTimer);
		const notice = article.querySelector('.kd-whats-new-notice');
		if (!notice) return;
		const start = () => {
			clearTimeout(noticeTimer);
			noticeTimer = setTimeout(() => retireNotice(notice), noticeLifetimeMs);
		};
		notice.addEventListener('mouseenter', () => clearTimeout(noticeTimer));
		notice.addEventListener('focusin', () => clearTimeout(noticeTimer));
		notice.addEventListener('mouseleave', () => { if (!notice.contains(document.activeElement)) start(); });
		notice.addEventListener('focusout', event => { if (!notice.contains(event.relatedTarget) && !notice.matches(':hover')) start(); });
		start();
	}

	// Collapsed rather than removed outright, so the patch below slides up instead of jumping.
	function retireNotice(notice) {
		if (!notice.isConnected) return;
		if (matchMedia('(prefers-reduced-motion: reduce)').matches) {
			notice.remove();
			return;
		}
		notice.style.height = `${notice.offsetHeight}px`;
		void notice.offsetHeight;
		notice.classList.add('is-leaving');
		notice.addEventListener('transitionend', event => { if (event.propertyName === 'height') notice.remove(); });
		setTimeout(() => notice.remove(), 800);
	}

	// Dismissing ends the What's New visit: the highlights go, and the address becomes the plain
	// page so a reload or a bookmark does not bring the notice back.
	document.addEventListener('click', event => {
		if (!event.target.closest('[data-whats-new-dismiss]')) return;
		clearTimeout(noticeTimer);
		article.querySelectorAll('.kd-whats-new-notice').forEach(n => n.remove());
		article.querySelectorAll('.kd-patch--new').forEach(s => s.classList.remove('kd-patch--new'));
		article.querySelectorAll('.kd-badge-new').forEach(b => b.remove());
		if (whatsNewView && whatsNewView.pageKey) {
			try {
				const url = location.href.split('#')[0].split('?')[0] + href(whatsNewView.pageKey);
				history.replaceState(null, '', url);
				currentId = whatsNewView.pageKey;
				document.title = `${docs.pages[currentId].title} — ${siteTitle}`;
			} catch { /* some embedded origins refuse history writes; the view is already clean */ }
		}
	});

	toc.addEventListener('click', event => {
		const link = event.target.closest('a[data-target]');
		if (!link || !whatsNewView || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey) return;
		const target = document.getElementById(link.dataset.target);
		if (!target) return;
		event.preventDefault();
		target.scrollIntoView({ block: 'start' });
	});

	// A link to the route already in the address bar raises no hashchange, so re-clicking a TOC entry
	// after scrolling away from it would do nothing. Scroll to it directly instead.
	document.addEventListener('click', event => {
		const link = event.target.closest('a[href^="#/"]');
		if (!link || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey) return;
		if (link.getAttribute('href') === location.hash) {
			event.preventDefault();
			render();
		}
	});

	/* ---------- search ---------- */

	const index = (docs.search || []).map((entry, position) => ({
		...entry,
		position,
		titleLower: entry.title.toLowerCase(),
		headingLower: (entry.heading || '').toLowerCase(),
		textLower: (entry.text || '').toLowerCase()
	}));
	const sectionTitles = Object.fromEntries(docs.sections.map(s => [s.id, s.title]));
	let activeResult = -1;

	function tokens(query) {
		return query.toLowerCase().split(/\s+/).filter(Boolean);
	}

	function score(entry, words, phrase) {
		let total = 0;
		for (const word of words) {
			const inHeading = entry.headingLower.includes(word);
			const inTitle = entry.titleLower.includes(word);
			const inText = entry.textLower.includes(word);
			if (!inHeading && !inTitle && !inText) return 0;
			total += (inHeading ? 6 : 0) + (inTitle ? 4 : 0) + (inText ? 1 : 0);
		}
		if (words.length > 1 && (entry.headingLower.includes(phrase) || entry.textLower.includes(phrase))) total += 8;
		return total;
	}

	function highlight(text, words) {
		let html = escapeHtml(text);
		for (const word of words) {
			const pattern = new RegExp(`(${escapeHtml(word).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
			html = html.replace(pattern, '<mark>$1</mark>');
		}
		return html;
	}

	function snippet(entry, words) {
		const text = entry.text || '';
		let at = -1;
		for (const word of words) {
			const found = entry.textLower.indexOf(word);
			if (found !== -1 && (at === -1 || found < at)) at = found;
		}
		if (at === -1) return text.slice(0, 150) + (text.length > 150 ? '…' : '');
		const start = Math.max(0, at - 50);
		const end = Math.min(text.length, start + 160);
		return (start > 0 ? '…' : '') + text.slice(start, end) + (end < text.length ? '…' : '');
	}

	function closeResults() {
		results.hidden = true;
		results.innerHTML = '';
		search.setAttribute('aria-expanded', 'false');
		search.removeAttribute('aria-activedescendant');
		activeResult = -1;
	}

	function runSearch() {
		const query = search.value.trim();
		const words = tokens(query);
		if (!words.length) {
			closeResults();
			return;
		}

		const phrase = words.join(' ');
		const hits = index
			.map(entry => ({ entry, score: score(entry, words, phrase) }))
			.filter(hit => hit.score > 0)
			.sort((a, b) => b.score - a.score || a.entry.position - b.entry.position)
			.slice(0, 20);

		if (!hits.length) {
			results.innerHTML = `<li class="kd-search-empty">Nothing matches <strong>${escapeHtml(query)}</strong>.</li>`;
		} else {
			results.innerHTML = hits.map(({ entry }, i) => {
				const where = entry.heading && entry.heading !== entry.title ? `${entry.title} › ${entry.heading}` : entry.title;
				return `<li role="presentation"><a id="kdResult${i}" role="option" href="${href(entry.page, entry.anchor)}">` +
					`<span class="kd-sr-title"><span class="kd-sr-section">${escapeHtml(sectionTitles[entry.section] || entry.section)}</span>${highlight(where, words)}</span>` +
					`<span class="kd-sr-text">${highlight(snippet(entry, words), words)}</span></a></li>`;
			}).join('');
		}
		results.hidden = false;
		search.setAttribute('aria-expanded', 'true');
		activeResult = -1;
	}

	function setActiveResult(next) {
		const links = [...results.querySelectorAll('a')];
		if (!links.length) return;
		activeResult = (next + links.length) % links.length;
		links.forEach((a, i) => a.classList.toggle('is-active', i === activeResult));
		const active = links[activeResult];
		search.setAttribute('aria-activedescendant', active.id);
		active.scrollIntoView({ block: 'nearest' });
	}

	search.addEventListener('input', runSearch);
	search.addEventListener('focus', () => { if (search.value.trim()) runSearch(); });
	search.addEventListener('keydown', event => {
		if (event.key === 'ArrowDown') { event.preventDefault(); setActiveResult(activeResult + 1); }
		else if (event.key === 'ArrowUp') { event.preventDefault(); setActiveResult(activeResult - 1); }
		else if (event.key === 'Enter') {
			const links = results.querySelectorAll('a');
			const target = links[activeResult] || links[0];
			if (target) { event.preventDefault(); target.click(); }
		} else if (event.key === 'Escape') {
			if (!results.hidden) closeResults();
			else { search.value = ''; search.blur(); }
		}
	});
	results.addEventListener('click', event => {
		if (event.target.closest('a')) { closeResults(); search.blur(); }
	});
	document.addEventListener('pointerdown', event => {
		if (!event.target.closest('.kd-search-wrap')) closeResults();
	});
	document.addEventListener('keydown', event => {
		if (event.key !== '/' || event.ctrlKey || event.metaKey || event.altKey) return;
		const typing = event.target.closest?.('input, textarea, select, [contenteditable="true"]');
		if (typing) return;
		event.preventDefault();
		search.focus();
		search.select();
	});

	/* ---------- article interactions ---------- */

	function showToast(text) {
		toast.textContent = text;
		toast.classList.add('show');
		clearTimeout(showToast.timer);
		showToast.timer = setTimeout(() => toast.classList.remove('show'), 1300);
	}

	// navigator.clipboard is refused outright on some file:// and embedded origins, and it reports
	// that as a rejected Promise, not a throw - so the fallback hangs off .catch, not try/catch.
	function copyText(value) {
		const legacyCopy = () => {
			const textarea = document.createElement('textarea');
			textarea.value = value;
			textarea.style.position = 'fixed';
			textarea.style.opacity = '0';
			document.body.appendChild(textarea);
			textarea.select();
			try { document.execCommand('copy'); } catch { /* nothing further to fall back to */ }
			document.body.removeChild(textarea);
		};
		if (navigator.clipboard?.writeText) return navigator.clipboard.writeText(value).catch(legacyCopy);
		legacyCopy();
		return Promise.resolve();
	}

	// The three ways into a tour step - the numbered pin, the region drawn over the screenshot, and
	// the card below it - all resolve to the same id, so they are one control with three surfaces.
	// Passing null clears the tour, which is what re-clicking the open step does.
	function setTourStep(tour, target) {
		tour.querySelectorAll('[data-help-tour-target]').forEach(item => {
			const active = item.dataset.helpTourTarget === target;
			item.classList.toggle('active', active);
			if (item.tagName === 'BUTTON') item.setAttribute('aria-pressed', active ? 'true' : 'false');
		});
		tour.querySelectorAll('[data-help-tour-region]').forEach(region =>
			region.classList.toggle('active', region.dataset.helpTourRegion === target));
	}

	function tourIdOf(el) {
		return el.dataset.helpTourTarget || el.dataset.helpTourRegion;
	}

	function setTourHover(el, on) {
		const tour = el.closest('[data-help-tour]');
		if (!tour) return;
		const id = tourIdOf(el);
		tour.querySelectorAll(`[data-help-tour-region="${CSS.escape(id)}"],.cc-help-tour-pin[data-help-tour-target="${CSS.escape(id)}"]`)
			.forEach(node => node.classList.toggle('hover', on));
	}

	document.addEventListener('pointerover', event => {
		const region = event.target.closest?.('[data-help-tour-region]');
		if (region) setTourHover(region, true);
	});

	document.addEventListener('pointerout', event => {
		const region = event.target.closest?.('[data-help-tour-region]');
		if (region) setTourHover(region, false);
	});

	document.addEventListener('click', event => {
		const tourHit = event.target.closest('[data-help-tour-target],[data-help-tour-region]');
		if (tourHit) {
			const tour = tourHit.closest('[data-help-tour]');
			const target = tourHit.classList.contains('active') ? null : tourIdOf(tourHit);
			setTourStep(tour, target);
			return;
		}

		const copy = event.target.closest('[data-help-copy]');
		if (copy) {
			copyText(copy.dataset.helpCopy || '').then(() => {
				copy.classList.add('copied');
				showToast('Copied');
				setTimeout(() => copy.classList.remove('copied'), 1200);
			});
		}
	});

	// Release Differences demo: the pending toggle swaps the base block for the pending one.
	document.addEventListener('change', event => {
		const box = event.target.closest('#diffPendingToggleHelp input');
		if (!box) return;
		document.getElementById('diffPendingBlockHelp')?.classList.toggle('visible', box.checked);
		document.getElementById('diffBaseBlockHelp')?.classList.toggle('hidden', box.checked);
	});

	// Globals the dashboard samples call from inline attributes. In the app they belong to the
	// dashboard script; here they are only what a sample needs to behave sensibly on its own.
	window.wiCopy = (text, el) => {
		copyText(String(text ?? ''));
		const flash = el?.querySelector('.copy-toast');
		if (!flash) return;
		flash.classList.add('visible');
		setTimeout(() => flash.classList.remove('visible'), 1500);
	};
	window.scrollToCard = () => { /* the sample has no card to scroll to */ };

	/* ---------- boot ---------- */

	// A local -Preview build carries the Unreleased draft; say so on every page so a screenshot of it
	// is never mistaken for the published site.
	if (docs.preview) {
		document.body.classList.add('kd-is-preview');
		document.body.insertAdjacentHTML('afterbegin', '<div class="kd-preview-banner" role="note">Local draft preview: includes Unreleased notes. Never publish this build.</div>');
	}

	buildNav();
	window.addEventListener('hashchange', render);
	render();
})();
